// The 5-colour palette of an image: twin of tv-app PaletteExtract.kt (k-means in OKLab over a
// small thumbnail, deterministic, dark to light). test/fixtures/palette-extract-cases.json,
// generated by the Kotlin test, keeps the two in step.

import { oklabToSrgb, srgbToOklab } from './palette.ts';

export const K = 5;
export const ITERATIONS = 12;

/** `rgba`: RGBA bytes (alpha ignored), any size >= 5 pixels. Returns 15 floats, sRGB 0..1. */
export function extractPalette(rgba: Uint8Array | Uint8ClampedArray): Float32Array {
  const n = Math.floor(rgba.length / 4);
  if (n < K) throw new Error(`need at least ${K} pixels`);
  const lab = new Float64Array(n * 3);
  for (let i = 0; i < n; i++) srgbToOklab(rgba[i * 4]! / 255, rgba[i * 4 + 1]! / 255, rgba[i * 4 + 2]! / 255, lab, i * 3);
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => lab[a * 3]! - lab[b * 3]! || a - b);
  const c = new Float64Array(K * 3);
  for (let k = 0; k < K; k++) {
    const idx = order[Math.trunc((0.1 + 0.2 * k) * (n - 1))]!;
    for (let d = 0; d < 3; d++) c[k * 3 + d] = lab[idx * 3 + d]!;
  }
  const sum = new Float64Array(K * 3);
  const count = new Int32Array(K);
  for (let it = 0; it < ITERATIONS; it++) {
    sum.fill(0);
    count.fill(0);
    for (let i = 0; i < n; i++) {
      let best = 0;
      let bestD = Number.MAX_VALUE;
      for (let k = 0; k < K; k++) {
        const dl = lab[i * 3]! - c[k * 3]!;
        const da = lab[i * 3 + 1]! - c[k * 3 + 1]!;
        const db = lab[i * 3 + 2]! - c[k * 3 + 2]!;
        const dd = dl * dl + da * da + db * db;
        if (dd < bestD) {
          bestD = dd;
          best = k;
        }
      }
      count[best]!++;
      for (let d = 0; d < 3; d++) sum[best * 3 + d]! += lab[i * 3 + d]!;
    }
    for (let k = 0; k < K; k++) if (count[k]! > 0) for (let d = 0; d < 3; d++) c[k * 3 + d] = sum[k * 3 + d]! / count[k]!;
  }
  const byL = Array.from({ length: K }, (_, k) => k).sort((a, b) => c[a * 3]! - c[b * 3]! || a - b);
  const out = new Float32Array(K * 3);
  byL.forEach((k, j) => oklabToSrgb(c[k * 3]!, c[k * 3 + 1]!, c[k * 3 + 2]!, out, j * 3));
  return out;
}
